<?php
declare(strict_types=1);
require_once __DIR__ . '/auth.php';
adminRequireAuth();
$root=dirname(__DIR__);$file=$root.'/data/jamoa.json';$notice='';$error='';$default=['intro'=>'','hero_image'=>'','team'=>[]];
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function readTeam(string $file,array $default):array{$raw=is_file($file)?file_get_contents($file):false;$data=is_string($raw)?json_decode($raw,true):null;if(!is_array($data))$data=$default;foreach($default as $k=>$v){if(!array_key_exists($k,$data))$data[$k]=$v;if(is_array($v)&&!is_array($data[$k]))$data[$k]=$v;}return $data;}
function rowsToJson(string $raw):array{$out=[];foreach(preg_split('/\R/',$raw)?:[] as $line){$line=trim($line);if($line==='')continue;$item=json_decode($line,true);if(!is_array($item))throw new RuntimeException('Team: har bir qator valid JSON object bo‘lishi kerak.');$out[]=$item;}return $out;}
function jsonLines(mixed $value):string{$out=[];if(!is_array($value))return '';foreach($value as $item){if(!is_array($item))continue;$json=json_encode($item,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($json!==false)$out[]=$json;}return implode("\n",$out);}
$data=readTeam($file,$default);
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!adminVerifyCsrf((string)($_POST['csrf']??'')))throw new RuntimeException('CSRF token noto‘g‘ri yoki sessiya eskirgan.');$intro=trim((string)($_POST['intro']??''));$hero=trim((string)($_POST['hero_image']??''));$teamRaw=trim((string)($_POST['team']??''));if($hero!==''&&!preg_match('#^(?:https?://|/|\.\./|media/)#i',$hero))throw new RuntimeException('Hero image path xavfsiz formatda emas.');$team=$teamRaw===''?[]:rowsToJson($teamRaw);$payload=['intro'=>$intro,'hero_image'=>$hero,'team'=>$team];$json=json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($json===false||file_put_contents($file,$json.PHP_EOL,LOCK_EX)===false)throw new RuntimeException('JSON faylini saqlash amalga oshmadi.');$data=$payload;$notice='Jamoa kontenti saqlandi.';}catch(Throwable $ex){$error=$ex->getMessage();}}
